with filtered as (select *, coalesce(unit_price, 0) as unit_price_filled, case when quantity >= 7 then 'High' when quantity >= 4 then 'Medium' else 'Low' end as quantity_band from order_items where unit_price >= 340) select order_id, case when unit_price >= 400 then 'PREMIUM' else 'STANDARD' end as unit_price_tier, approx_percentile(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, stddev_samp(quantity) as quantity_stddev, bit_or(quantity) as quantity_bit_or from filtered group by 1, 2 order by unit_price_tier desc;
